const fs = require('fs');
const [N, T] = fs.readFileSync(0, 'utf8').trim().split(/\s+/).map(Number);

let ans;
if (T === 0) {
  ans = N;
} else if (T === 1) {
  ans = N * (N - 1);
} else {
  ans = (N * (N - 1) * (N - 2)) / 6;
}

console.log(ans);
